1	package com.example.starter.quarantine.service;
2	
3	import com.example.starter.quarantine.ArrivalResult;
4	import com.example.starter.quarantine.CertificateStatus;
5	import com.example.starter.quarantine.DeclarationStatus;
6	import com.example.starter.quarantine.Species;
7	import com.example.starter.quarantine.api.ApiDtos.ArrivalCmd;
8	import com.example.starter.quarantine.api.ApiDtos.ArrivalView;
9	import com.example.starter.quarantine.api.ApiDtos.CertificateView;
10	import com.example.starter.quarantine.api.ApiDtos.DeclarationCmd;
11	import com.example.starter.quarantine.api.ApiDtos.DeclarationView;
12	import com.example.starter.quarantine.api.ApiDtos.DepartCmd;
13	import com.example.starter.quarantine.api.ApiDtos.IssueCmd;
14	import com.example.starter.quarantine.api.ApiDtos.LockdownCmd;
15	import com.example.starter.quarantine.api.ApiDtos.LockdownView;
16	import com.example.starter.quarantine.api.ApiDtos.StockCmd;
17	import com.example.starter.quarantine.api.ApiDtos.StockView;
18	import com.example.starter.quarantine.api.ApiException;
19	import com.example.starter.quarantine.model.Rows.ArrivalRow;
20	import com.example.starter.quarantine.model.Rows.CertificateRow;
21	import com.example.starter.quarantine.model.Rows.DeclarationRow;
22	import com.example.starter.quarantine.model.Rows.LockdownRow;
23	import com.example.starter.quarantine.repo.QuarantineRepository;
24	import java.nio.charset.StandardCharsets;
25	import java.security.MessageDigest;
26	import java.security.NoSuchAlgorithmException;
27	import java.time.Clock;
28	import java.time.Instant;
29	import java.util.HexFormat;
30	import java.util.List;
31	import org.springframework.dao.DuplicateKeyException;
32	import org.springframework.stereotype.Service;
33	import org.springframework.transaction.annotation.Transactional;
34	
35	/**
36	 * 动物调运检疫出证与疫点封锁联动服务。
37	 *
38	 * <p>幂等约定：申报、出证、落地报告均以 requestId 为幂等键，指纹覆盖 requestId 与全部业务字段；
39	 * 同键同参返回首次结果，同键异参返回 409 且不改变单据状态。
40	 *
41	 * <p>并发约定：封锁发布、出证、启运在同一养殖场登记行上以 SELECT ... FOR UPDATE 串行化，
42	 * 保证封锁生效与正常出证不会同时成立；同一证的落地报告以证行排他锁串行化。
43	 */
44	@Service
45	public class QuarantineService {
46	
47	    private static final String LOCKDOWN_REJECT_REASON = "产地被划为疫点封锁区，申报驳回";
48	
49	    private final QuarantineRepository repo;
50	    private final Clock clock;
51	
52	    public QuarantineService(QuarantineRepository repo, Clock businessClock) {
53	        this.repo = repo;
54	        this.clock = businessClock;
55	    }
56	
57	    // ---------- 检疫申报 ----------
58	
59	    /**
60	     * 检疫申报。幂等；申报时养殖场已处于封锁区的，申报单直接落库为已驳回。
61	     */
62	    @Transactional
63	    public DeclarationView declare(DeclarationCmd cmd) {
64	        String fingerprint = fingerprint(cmd.requestId(), cmd.farmId(), cmd.destination(),
65	                cmd.species().name(), String.valueOf(cmd.quantity()), cmd.earTagRange());
66	        return repo.findDeclarationByRequestId(cmd.requestId())
67	                .map(existing -> replayDeclaration(existing, fingerprint))
68	                .orElseGet(() -> createDeclaration(cmd, fingerprint));
69	    }
70	
71	    private DeclarationView createDeclaration(DeclarationCmd cmd, String fingerprint) {
72	        Instant now = clock.instant();
73	        repo.ensureFarmRegistry(cmd.farmId(), now);
74	        // 与封锁发布串行化：持锁期间封锁要么已生效（本单驳回），要么未生效（封锁随后会驳回本单）。
75	        repo.lockFarm(cmd.farmId());
76	        boolean locked = repo.findActiveLockdownByFarm(cmd.farmId()).isPresent();
77	        DeclarationStatus status = locked ? DeclarationStatus.REJECTED : DeclarationStatus.DECLARED;
78	        String rejectReason = locked ? LOCKDOWN_REJECT_REASON : null;
79	        try {
80	            repo.insertDeclaration(cmd.requestId(), fingerprint, cmd.farmId(), cmd.destination(),
81	                    cmd.species(), cmd.quantity(), cmd.earTagRange(), status, rejectReason, now);
82	        } catch (DuplicateKeyException e) {
83	            // 并发同键申报：以先提交者为准。
84	            return repo.findDeclarationByRequestId(cmd.requestId())
85	                    .map(existing -> replayDeclaration(existing, fingerprint))
86	                    .orElseThrow(() -> e);
87	        }
88	        return repo.findDeclarationByRequestId(cmd.requestId())
89	                .map(this::toDeclarationView)
90	                .orElseThrow(() -> new IllegalStateException("申报写入后读取失败"));
91	    }
92	
93	    private DeclarationView replayDeclaration(DeclarationRow existing, String fingerprint) {
94	        if (!existing.fingerprint().equals(fingerprint)) {
95	            throw ApiException.conflict("requestId 已存在且业务参数不一致，拒绝重放");
96	        }
97	        return toDeclarationView(existing);
98	    }
99	
100	    // ---------- 出证 ----------
101	
102	    /**
103	     * 出证：核减可售存栏与生成证号在同一事务；同一养殖场同批动物（耳标段）仅允许一张有效证，
104	     * 重复出证按幂等处理返回已有证。
105	     */
106	    @Transactional
107	    public CertificateView issue(IssueCmd cmd) {
108	        return repo.findCertByIssueRequestId(cmd.requestId())
109	                .map(existing -> replayIssue(existing, cmd))
110	                .orElseGet(() -> createCertificate(cmd));
111	    }
112	
113	    private CertificateView createCertificate(IssueCmd cmd) {
114	        DeclarationRow declaration = repo.findDeclarationByRequestId(cmd.declarationRequestId())
115	                .orElseThrow(() -> ApiException.notFound("申报单不存在: " + cmd.declarationRequestId()));
116	        String fingerprint = fingerprint(cmd.requestId(), cmd.declarationRequestId());
117	        Instant now = clock.instant();
118	        repo.ensureFarmRegistry(declaration.farmId(), now);
119	        // 与封锁发布串行化：持锁后封锁要么已生效（拒绝出证），要么未生效（封锁随后作废/标记本证）。
120	        repo.lockFarm(declaration.farmId());
121	        if (repo.findActiveLockdownByFarm(declaration.farmId()).isPresent()) {
122	            throw ApiException.unprocessable("产地处于疫点封锁区，禁止出证");
123	        }
124	        if (declaration.status() == DeclarationStatus.REJECTED) {
125	            throw ApiException.unprocessable("申报已被驳回，禁止出证");
126	        }
127	        if (declaration.status() == DeclarationStatus.CERTIFIED) {
128	            return repo.findCertByDeclarationRequestId(cmd.declarationRequestId())
129	                    .map(this::toCertificateView)
130	                    .orElseThrow(() -> new IllegalStateException("申报已出证但证书缺失"));
131	        }
132	        // 同批动物仅允许一张有效证：重复出证按幂等处理，返回已有证。
133	        var heldCertNo = repo.findHoldCertNo(declaration.farmId(), declaration.earTagRange());
134	        if (heldCertNo.isPresent()) {
135	            return repo.findCertByNo(heldCertNo.get())
136	                    .map(this::toCertificateView)
137	                    .orElseThrow(() -> new IllegalStateException("批次占用记录指向的证书缺失"));
138	        }
139	        // 核减可售存栏（原子条件更新），不足则整体失败。
140	        int decremented = repo.decrementStock(declaration.farmId(), declaration.species(),
141	                declaration.earTagRange(), declaration.quantity(), now);
142	        if (decremented == 0) {
143	            throw ApiException.unprocessable("可售存栏不足，出证失败");
144	        }
145	        Instant issuedAt = now;
146	        Instant expiresAt = issuedAt.plusSeconds(declaration.species().validityHours() * 3600L);
147	        // 唯一键（issue_request_id、批次占用）作为并发兜底：冲突时本事务回滚，
148	        // 由 IssueExecutor 在新事务中重放先提交结果。
149	        long id = repo.insertCertificate("TMP-" + cmd.requestId(), cmd.requestId(), fingerprint,
150	                declaration.requestId(), declaration.farmId(), declaration.destination(),
151	                declaration.species(), declaration.quantity(), declaration.earTagRange(),
152	                issuedAt, expiresAt, now);
153	        String certNo = String.format("AQ%08d", id);
154	        repo.updateCertNo(id, certNo, now);
155	        repo.insertHold(declaration.farmId(), declaration.earTagRange(), certNo, now);
156	        repo.markDeclarationCertified(declaration.requestId(), now);
157	        return repo.findCertByIssueRequestId(cmd.requestId())
158	                .map(this::toCertificateView)
159	                .orElseThrow(() -> new IllegalStateException("证书写入后读取失败"));
160	    }
161	
162	    private CertificateView replayIssue(CertificateRow existing, IssueCmd cmd) {
163	        String fingerprint = fingerprint(cmd.requestId(), cmd.declarationRequestId());
164	        if (!existing.fingerprint().equals(fingerprint)) {
165	            throw ApiException.conflict("requestId 已存在且业务参数不一致，拒绝重放");
166	        }
167	        return toCertificateView(existing);
168	    }
169	
170	    // ---------- 启运 ----------
171	
172	    /**
173	     * 启运：已出证未启运 → 调运在途。重复启运返回当前证状态（幂等）。
174	     */
175	    @Transactional
176	    public CertificateView depart(DepartCmd cmd) {
177	        CertificateRow cert = repo.findCertByNo(cmd.certNo())
178	                .orElseThrow(() -> ApiException.notFound("证书不存在: " + cmd.certNo()));
179	        Instant now = clock.instant();
180	        repo.ensureFarmRegistry(cert.farmId(), now);
181	        repo.lockFarm(cert.farmId());
182	        CertificateRow locked = repo.findCertByNo(cmd.certNo()).orElseThrow();
183	        if (locked.status() == CertificateStatus.IN_TRANSIT) {
184	            return toCertificateView(locked);
185	        }
186	        if (locked.status() != CertificateStatus.ISSUED) {
187	            throw ApiException.unprocessable("证状态不允许启运: " + locked.status());
188	        }
189	        if (repo.findActiveLockdownByFarm(locked.farmId()).isPresent()) {
190	            throw ApiException.unprocessable("产地处于疫点封锁区，禁止启运");
191	        }
192	        repo.markDeparted(cmd.certNo(), now, now);
193	        return repo.findCertByNo(cmd.certNo()).map(this::toCertificateView).orElseThrow();
194	    }
195	
196	    // ---------- 疫点封锁 ----------
197	
198	    /**
199	     * 发布疫点封锁：即刻生效。未出证申报一律驳回；已出证未启运的证自动作废；
200	     * 已在途的允许完成落地但强制隔离观察标记。
201	     */
202	    @Transactional
203	    public LockdownView lockdown(LockdownCmd cmd) {
204	        String fingerprint = fingerprint(cmd.requestId(), cmd.farmId(), cmd.reason());
205	        var byRequest = repo.findLockdownByRequestId(cmd.requestId());
206	        if (byRequest.isPresent()) {
207	            LockdownRow existing = byRequest.get();
208	            if (!existing.fingerprint().equals(fingerprint)) {
209	                throw ApiException.conflict("requestId 已存在且业务参数不一致，拒绝重放");
210	            }
211	            return toLockdownView(existing, 0, 0, 0);
212	        }
213	        var byFarm = repo.findActiveLockdownByFarm(cmd.farmId());
214	        if (byFarm.isPresent()) {
215	            return toLockdownView(byFarm.get(), 0, 0, 0);
216	        }
217	        Instant now = clock.instant();
218	        repo.ensureFarmRegistry(cmd.farmId(), now);
219	        repo.lockFarm(cmd.farmId());
220	        // 持锁后复查，避免与并发封锁重复生效。
221	        var recheck = repo.findActiveLockdownByFarm(cmd.farmId());
222	        if (recheck.isPresent()) {
223	            return toLockdownView(recheck.get(), 0, 0, 0);
224	        }
225	        repo.insertLockdown(cmd.requestId(), fingerprint, cmd.farmId(), cmd.reason(), now);
226	        int rejected = repo.rejectPendingDeclarations(cmd.farmId(), LOCKDOWN_REJECT_REASON, now);
227	        List<String> voided = repo.voidIssuedCertsByFarm(cmd.farmId(), now);
228	        voided.forEach(repo::deleteHoldByCertNo);
229	        int quarantined = repo.markInTransitQuarantineByFarm(cmd.farmId(), now);
230	        LockdownRow row = repo.findLockdownByRequestId(cmd.requestId()).orElseThrow();
231	        return toLockdownView(row, rejected, voided.size(), quarantined);
232	    }
233	
234	    // ---------- 落地报告 ----------
235	
236	    /**
237	     * 落地报告。幂等；恰在有效期终点前（含终点）有效，超时拒绝并将证标记证失效；
238	     * 累计数量恰等于证载数量即结案，超量整批拒绝；结案为终态，迟到事件只记录不改状态。
239	     */
240	    @Transactional
241	    public ArrivalView arrive(ArrivalCmd cmd) {
242	        String fingerprint = fingerprint(cmd.requestId(), cmd.certNo(), String.valueOf(cmd.quantity()));
243	        return repo.findArrivalByRequestId(cmd.requestId())
244	                .map(existing -> replayArrival(existing, fingerprint))
245	                .orElseGet(() -> processArrival(cmd, fingerprint));
246	    }
247	
248	    private ArrivalView processArrival(ArrivalCmd cmd, String fingerprint) {
249	        CertificateRow cert = repo.findCertByNoForUpdate(cmd.certNo())
250	                .orElseThrow(() -> ApiException.notFound("证书不存在: " + cmd.certNo()));
251	        // 持证行锁后复查幂等键，防止并发同键报告重复入账。
252	        var existing = repo.findArrivalByRequestId(cmd.requestId());
253	        if (existing.isPresent()) {
254	            return replayArrival(existing.get(), fingerprint);
255	        }
256	        Instant now = clock.instant();
257	        ArrivalResult result;
258	        String note = null;
259	        switch (cert.status()) {
260	            case CLOSED -> {
261	                result = ArrivalResult.LATE_IGNORED;
262	                note = "证已结案，迟到事件只记录不改状态";
263	            }
264	            case VOIDED, EXPIRED -> {
265	                result = ArrivalResult.REJECTED_CERT_INVALID;
266	                note = "证状态为 " + cert.status() + "，拒绝落地报告";
267	            }
268	            case ISSUED -> {
269	                result = ArrivalResult.REJECTED_NOT_IN_TRANSIT;
270	                note = "证未启运，拒绝落地报告";
271	            }
272	            case IN_TRANSIT -> {
273	                if (now.isAfter(cert.expiresAt())) {
274	                    repo.updateCertStatus(cert.certNo(), CertificateStatus.EXPIRED, now);
275	                    repo.deleteHoldByCertNo(cert.certNo());
276	                    result = ArrivalResult.REJECTED_EXPIRED;
277	                    note = "超过有效期终点，证失效";
278	                } else {
279	                    long cumulative = (long) cert.reportedQty() + cmd.quantity();
280	                    if (cumulative > cert.quantity()) {
281	                        result = ArrivalResult.REJECTED_OVERFLOW;
282	                        note = "累计数量超过证载数量，整批拒绝";
283	                    } else if (cumulative == cert.quantity()) {
284	                        repo.closeCert(cert.certNo(), (int) cumulative, now, now);
285	                        repo.deleteHoldByCertNo(cert.certNo());
286	                        result = ArrivalResult.ACCEPTED_FINAL;
287	                    } else {
288	                        repo.updateReportedQty(cert.certNo(), (int) cumulative, now);
289	                        result = ArrivalResult.ACCEPTED_PARTIAL;
290	                    }
291	                }
292	            }
293	            default -> throw new IllegalStateException("未知证状态: " + cert.status());
294	        }
295	        repo.insertArrival(cmd.requestId(), fingerprint, cmd.certNo(), cmd.quantity(),
296	                result, note, now);
297	        CertificateRow after = repo.findCertByNo(cmd.certNo()).orElseThrow();
298	        ArrivalRow row = repo.findArrivalByRequestId(cmd.requestId()).orElseThrow();
299	        return toArrivalView(row, after);
300	    }
301	
302	    private ArrivalView replayArrival(ArrivalRow existing, String fingerprint) {
303	        if (!existing.fingerprint().equals(fingerprint)) {
304	            throw ApiException.conflict("requestId 已存在且业务参数不一致，拒绝重放");
305	        }
306	        CertificateRow cert = repo.findCertByNo(existing.certNo())
307	                .orElseThrow(() -> new IllegalStateException("落地报告指向的证书缺失"));
308	        return toArrivalView(existing, cert);
309	    }
310	
311	    // ---------- 可售存栏（合成数据入口） ----------
312	
313	    /**
314	     * 登记/覆盖养殖场可售存栏。
315	     */
316	    @Transactional
317	    public StockView upsertStock(StockCmd cmd) {
318	        Instant now = clock.instant();
319	        repo.ensureFarmRegistry(cmd.farmId(), now);
320	        repo.upsertStock(cmd.farmId(), cmd.species(), cmd.earTagRange(), cmd.quantity(), now);
321	        return new StockView(cmd.farmId(), cmd.species(), cmd.earTagRange(), cmd.quantity());
322	    }
323	
324	    // ---------- 查询 ----------
325	
326	    @Transactional(readOnly = true)
327	    public DeclarationView getDeclaration(String requestId) {
328	        return repo.findDeclarationByRequestId(requestId)
329	                .map(this::toDeclarationView)
330	                .orElseThrow(() -> ApiException.notFound("申报单不存在: " + requestId));
331	    }
332	
333	    @Transactional(readOnly = true)
334	    public CertificateView getCertificate(String certNo) {
335	        return repo.findCertByNo(certNo)
336	                .map(this::toCertificateView)
337	                .orElseThrow(() -> ApiException.notFound("证书不存在: " + certNo));
338	    }
339	
340	    @Transactional(readOnly = true)
341	    public StockView getStock(String farmId, String species, String earTagRange) {
342	        return repo.findStock(farmId, Species.valueOf(species), earTagRange)
343	                .map(row -> new StockView(row.farmId(), row.species(), row.earTagRange(), row.sellableQty()))
344	                .orElseThrow(() -> ApiException.notFound("存栏记录不存在"));
345	    }
346	
347	    // ---------- 视图映射与指纹 ----------
348	
349	    private DeclarationView toDeclarationView(DeclarationRow row) {
350	        return new DeclarationView(row.requestId(), row.farmId(), row.destination(), row.species(),
351	                row.quantity(), row.earTagRange(), row.status(), row.rejectReason(), row.createdAt());
352	    }
353	
354	    private CertificateView toCertificateView(CertificateRow row) {
355	        return new CertificateView(row.certNo(), row.issueRequestId(), row.declarationRequestId(),
356	                row.farmId(), row.destination(), row.species(), row.quantity(), row.earTagRange(),
357	                row.status(), row.quarantineObservation(), row.reportedQty(),
358	                row.issuedAt(), row.expiresAt(), row.departedAt(), row.closedAt());
359	    }
360	
361	    private LockdownView toLockdownView(LockdownRow row, int rejected, int voided, int quarantined) {
362	        return new LockdownView(row.requestId(), row.farmId(), row.reason(), row.status(),
363	                row.createdAt(), rejected, voided, quarantined);
364	    }
365	
366	    private ArrivalView toArrivalView(ArrivalRow row, CertificateRow cert) {
367	        return new ArrivalView(row.requestId(), row.certNo(), row.quantity(), row.result(), row.note(),
368	                cert.status(), cert.quarantineObservation(), cert.reportedQty(), row.createdAt());
369	    }
370	
371	    /**
372	     * 幂等指纹：requestId 与全部业务字段的 SHA-256。
373	     */
374	    static String fingerprint(String... fields) {
375	        MessageDigest digest;
376	        try {
377	            digest = MessageDigest.getInstance("SHA-256");
378	        } catch (NoSuchAlgorithmException e) {
379	            throw new IllegalStateException(e);
380	        }
381	        for (String field : fields) {
382	            digest.update(field.getBytes(StandardCharsets.UTF_8));
383	            digest.update((byte) 0x1F);
384	        }
385	        return HexFormat.of().formatHex(digest.digest());
386	    }
387	}
