package com.example.starter.quarantine.api;

import com.example.starter.quarantine.api.ApiDtos.ArrivalCmd;
import com.example.starter.quarantine.api.ApiDtos.ArrivalView;
import com.example.starter.quarantine.api.ApiDtos.CertificateView;
import com.example.starter.quarantine.api.ApiDtos.DeclarationCmd;
import com.example.starter.quarantine.api.ApiDtos.DeclarationView;
import com.example.starter.quarantine.api.ApiDtos.DepartCmd;
import com.example.starter.quarantine.api.ApiDtos.IssueCmd;
import com.example.starter.quarantine.api.ApiDtos.LockdownCmd;
import com.example.starter.quarantine.api.ApiDtos.LockdownView;
import com.example.starter.quarantine.api.ApiDtos.StockCmd;
import com.example.starter.quarantine.api.ApiDtos.StockView;
import com.example.starter.quarantine.service.IssueExecutor;
import com.example.starter.quarantine.service.QuarantineService;
import jakarta.validation.Valid;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * 动物调运检疫出证与疫点封锁联动服务 REST 入口。
 */
@RestController
@RequestMapping("/api")
public class QuarantineController {

    private final QuarantineService service;
    private final IssueExecutor issueExecutor;

    public QuarantineController(QuarantineService service, IssueExecutor issueExecutor) {
        this.service = service;
        this.issueExecutor = issueExecutor;
    }

    /** 检疫申报（幂等）。 */
    @PostMapping("/quarantine/declarations")
    public DeclarationView declare(@Valid @RequestBody DeclarationCmd cmd) {
        return service.declare(cmd);
    }

    /** 查询申报单。 */
    @GetMapping("/quarantine/declarations/{requestId}")
    public DeclarationView getDeclaration(@PathVariable String requestId) {
        return service.getDeclaration(requestId);
    }

    /** 出证（幂等；核减存栏与生成证号同事务）。 */
    @PostMapping("/quarantine/certificates")
    public CertificateView issue(@Valid @RequestBody IssueCmd cmd) {
        return issueExecutor.execute(cmd);
    }

    /** 查询合格证。 */
    @GetMapping("/quarantine/certificates/{certNo}")
    public CertificateView getCertificate(@PathVariable String certNo) {
        return service.getCertificate(certNo);
    }

    /** 启运：已出证未启运 → 调运在途。 */
    @PostMapping("/quarantine/departures")
    public CertificateView depart(@Valid @RequestBody DepartCmd cmd) {
        return service.depart(cmd);
    }

    /** 发布疫点封锁（即刻生效，三级联动）。 */
    @PostMapping("/quarantine/lockdowns")
    public LockdownView lockdown(@Valid @RequestBody LockdownCmd cmd) {
        return service.lockdown(cmd);
    }

    /** 落地报告（幂等；结案为终态）。 */
    @PostMapping("/quarantine/arrivals")
    public ArrivalView arrive(@Valid @RequestBody ArrivalCmd cmd) {
        return service.arrive(cmd);
    }

    /** 登记/覆盖可售存栏（合成数据入口）。 */
    @PostMapping("/stocks")
    public StockView upsertStock(@Valid @RequestBody StockCmd cmd) {
        return service.upsertStock(cmd);
    }

    /** 查询可售存栏。 */
    @GetMapping("/stocks")
    public StockView getStock(@RequestParam String farmId,
                              @RequestParam String species,
                              @RequestParam String earTagRange) {
        return service.getStock(farmId, species, earTagRange);
    }
}

package com.example.starter.quarantine.api;

import com.example.starter.quarantine.ArrivalResult;
import com.example.starter.quarantine.CertificateStatus;
import com.example.starter.quarantine.DeclarationStatus;
import com.example.starter.quarantine.Species;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import java.time.Instant;

/**
 * 检疫服务 API 请求/响应模型。所有时间字段为 UTC。
 */
public final class ApiDtos {

    private ApiDtos() {
    }

    /** 检疫申报请求。 */
    public record DeclarationCmd(
            @NotBlank String requestId,
            @NotBlank String farmId,
            @NotBlank String destination,
            @NotNull Species species,
            @Positive int quantity,
            @NotBlank String earTagRange) {
    }

    /** 检疫申报视图。 */
    public record DeclarationView(
            String requestId,
            String farmId,
            String destination,
            Species species,
            int quantity,
            String earTagRange,
            DeclarationStatus status,
            String rejectReason,
            Instant createdAt) {
    }

    /** 出证请求。 */
    public record IssueCmd(
            @NotBlank String requestId,
            @NotBlank String declarationRequestId) {
    }

    /** 检疫合格证视图。 */
    public record CertificateView(
            String certNo,
            String issueRequestId,
            String declarationRequestId,
            String farmId,
            String destination,
            Species species,
            int quantity,
            String earTagRange,
            CertificateStatus status,
            boolean quarantineObservation,
            int reportedQty,
            Instant issuedAt,
            Instant expiresAt,
            Instant departedAt,
            Instant closedAt) {
    }

    /** 启运请求。 */
    public record DepartCmd(
            @NotBlank String requestId,
            @NotBlank String certNo) {
    }

    /** 疫点封锁发布请求。 */
    public record LockdownCmd(
            @NotBlank String requestId,
            @NotBlank String farmId,
            @NotBlank String reason) {
    }

    /** 疫点封锁发布结果，含三级联动处置统计。 */
    public record LockdownView(
            String requestId,
            String farmId,
            String reason,
            String status,
            Instant createdAt,
            int rejectedDeclarations,
            int voidedCertificates,
            int quarantinedInTransit) {
    }

    /** 落地报告请求。 */
    public record ArrivalCmd(
            @NotBlank String requestId,
            @NotBlank String certNo,
            @Positive int quantity) {
    }

    /** 落地报告处理结果视图。 */
    public record ArrivalView(
            String requestId,
            String certNo,
            int quantity,
            ArrivalResult result,
            String note,
            CertificateStatus certStatus,
            boolean quarantineObservation,
            int reportedQty,
            Instant createdAt) {
    }

    /** 可售存栏登记请求（合成数据入口）。 */
    public record StockCmd(
            @NotBlank String farmId,
            @NotNull Species species,
            @NotBlank String earTagRange,
            @Positive int quantity) {
    }

    /** 可售存栏视图。 */
    public record StockView(
            String farmId,
            Species species,
            String earTagRange,
            int sellableQty) {
    }

    /** 统一错误响应。 */
    public record ErrorView(String error, String message) {
    }
}

package com.example.starter.quarantine;

/**
 * 落地报告处理结果。
 */
public enum ArrivalResult {

    /** 部分到达已受理，累计数量未达证载数量。 */
    ACCEPTED_PARTIAL,
    /** 到达已受理，累计数量恰等于证载数量，证结案。 */
    ACCEPTED_FINAL,
    /** 超过有效期终点，拒绝并将证标记为证失效。 */
    REJECTED_EXPIRED,
    /** 累计数量超过证载数量，整批拒绝。 */
    REJECTED_OVERFLOW,
    /** 证未处于在途状态（未启运），拒绝。 */
    REJECTED_NOT_IN_TRANSIT,
    /** 证已作废或已失效，拒绝。 */
    REJECTED_CERT_INVALID,
    /** 证已结案，迟到事件只记录不改状态。 */
    LATE_IGNORED
}

package com.example.starter.quarantine;

/**
 * 检疫合格证状态机：ISSUED → IN_TRANSIT → CLOSED；封锁/超时触发 VOIDED/EXPIRED。
 */
public enum CertificateStatus {

    /** 已出证未启运。 */
    ISSUED,
    /** 调运在途。 */
    IN_TRANSIT,
    /** 已作废（出证后未启运即遇疫点封锁）。 */
    VOIDED,
    /** 证失效（超过有效期终点仍未完成落地）。 */
    EXPIRED,
    /** 已结案（终态，累计落地数量等于证载数量）。 */
    CLOSED
}

package com.example.starter.quarantine.model;

import com.example.starter.quarantine.ArrivalResult;
import com.example.starter.quarantine.CertificateStatus;
import com.example.starter.quarantine.DeclarationStatus;
import com.example.starter.quarantine.Species;
import java.time.Instant;

/**
 * 数据库行模型。所有时间字段为 UTC。
 */
public final class Rows {

    private Rows() {
    }

    /** 疫点封锁区行。 */
    public record LockdownRow(
            long id,
            String requestId,
            String fingerprint,
            String farmId,
            String reason,
            String status,
            Instant createdAt) {
    }

    /** 检疫申报行。 */
    public record DeclarationRow(
            long id,
            String requestId,
            String fingerprint,
            String farmId,
            String destination,
            Species species,
            int quantity,
            String earTagRange,
            DeclarationStatus status,
            String rejectReason,
            Instant createdAt) {
    }

    /** 检疫合格证行。 */
    public record CertificateRow(
            long id,
            String certNo,
            String issueRequestId,
            String fingerprint,
            String declarationRequestId,
            String farmId,
            String destination,
            Species species,
            int quantity,
            String earTagRange,
            CertificateStatus status,
            boolean quarantineObservation,
            int reportedQty,
            Instant issuedAt,
            Instant expiresAt,
            Instant departedAt,
            Instant closedAt) {
    }

    /** 可售存栏行。 */
    public record StockRow(
            long id,
            String farmId,
            Species species,
            String earTagRange,
            int sellableQty) {
    }

    /** 落地报告行。 */
    public record ArrivalRow(
            long id,
            String requestId,
            String fingerprint,
            String certNo,
            int quantity,
            ArrivalResult result,
            String note,
            Instant createdAt) {
    }
}

package com.example.starter.quarantine;

/**
 * 检疫申报状态。
 */
public enum DeclarationStatus {

    /** 已申报，等待出证。 */
    DECLARED,
    /** 已驳回（如申报时养殖场已处于疫点封锁区）。 */
    REJECTED,
    /** 已出证。 */
    CERTIFIED
}

