17	import org.junit.jupiter.api.Test;
18	import org.springframework.boot.test.context.SpringBootTest;
19	import org.springframework.http.HttpStatus;
20	
21	/**
22	 * 检疫业务主流程、失败分支与状态边界测试（真实 H2，可控时钟）。
23	 */
24	@SpringBootTest(properties = "spring.datasource.url=jdbc:h2:mem:quarantine_svc_test;"
25	        + "MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1")
26	class QuarantineServiceTest extends AbstractQuarantineIntegrationTest {
27	
28	    // ---------- 24/48 小时有效期边界 ----------
29	
30	    @Test
31	    void pigArrivalExactlyAt24hExpiryIsAcceptedAndCloses() {
32	        String farm = "F-PIG-24H";
33	        stock(farm, Species.PIG, "TAG-1", 10);
34	        DeclarationView declaration = declare("D-PIG-24H", farm, Species.PIG, 5, "TAG-1");
35	        CertificateView cert = issue("I-PIG-24H", declaration.requestId());
36	        assertThat(cert.expiresAt()).isEqualTo(cert.issuedAt().plus(Duration.ofHours(24)));
37	        depart(cert.certNo());
38	
39	        // 恰在有效期终点（T0+24h）落地：有效并结案。
40	        clock.setInstant(cert.expiresAt());
41	        ArrivalView arrival = service.arrive(new ArrivalCmd("A-PIG-24H", cert.certNo(), 5));
42	        assertThat(arrival.result()).isEqualTo(ArrivalResult.ACCEPTED_FINAL);
43	        assertThat(arrival.certStatus()).isEqualTo(CertificateStatus.CLOSED);
44	    }
45	
46	    @Test
47	    void pigArrivalOneSecondPast24hExpiryIsRejectedAndCertExpires() {
48	        String farm = "F-PIG-EXP";
49	        stock(farm, Species.PIG, "TAG-1", 10);
50	        DeclarationView declaration = declare("D-PIG-EXP", farm, Species.PIG, 5, "TAG-1");
51	        CertificateView cert = issue("I-PIG-EXP", declaration.requestId());
52	        depart(cert.certNo());
53	
54	        // 超过有效期终点 1 秒：拒绝并标记证失效。
55	        clock.setInstant(cert.expiresAt().plusSeconds(1));
56	        ArrivalView arrival = service.arrive(new ArrivalCmd("A-PIG-EXP", cert.certNo(), 5));
57	        assertThat(arrival.result()).isEqualTo(ArrivalResult.REJECTED_EXPIRED);
58	        assertThat(service.getCertificate(cert.certNo()).status()).isEqualTo(CertificateStatus.EXPIRED);
59	        // 证失效后同批动物有效证占用已释放。
60	        assertThat(countRows("cert_batch_hold")).isZero();
61	    }
62	
63	    @Test
64	    void poultryCertValidFor48h() {
65	        String farm = "F-POULTRY";
66	        stock(farm, Species.POULTRY, "TAG-9", 100);
67	        DeclarationView d1 = declare("D-POU-48H", farm, Species.POULTRY, 50, "TAG-9");
68	        CertificateView cert = issue("I-POU-48H", d1.requestId());
69	        assertThat(cert.expiresAt()).isEqualTo(cert.issuedAt().plus(Duration.ofHours(48)));
70	        depart(cert.certNo());
71	
72	        // 禽 48 小时终点前 1 秒：有效。
73	        clock.setInstant(cert.expiresAt().minusSeconds(1));
74	        ArrivalView arrival = service.arrive(new ArrivalCmd("A-POU-48H", cert.certNo(), 50));
75	        assertThat(arrival.result()).isEqualTo(ArrivalResult.ACCEPTED_FINAL);
76	    }
77	
78	    @Test
79	    void poultryArrivalPast48hExpiryIsRejected() {
80	        String farm = "F-POULTRY-EXP";
81	        stock(farm, Species.POULTRY, "TAG-9", 100);
82	        DeclarationView d1 = declare("D-POU-EXP", farm, Species.POULTRY, 50, "TAG-9");
83	        CertificateView cert = issue("I-POU-EXP", d1.requestId());
84	        depart(cert.certNo());
85	
86	        clock.setInstant(cert.expiresAt().plusSeconds(1));
87	        ArrivalView arrival = service.arrive(new ArrivalCmd("A-POU-EXP", cert.certNo(), 50));
88	        assertThat(arrival.result()).isEqualTo(ArrivalResult.REJECTED_EXPIRED);
89	        assertThat(service.getCertificate(cert.certNo()).status()).isEqualTo(CertificateStatus.EXPIRED);
90	    }
91	
92	    // ---------- 疫点封锁三级联动 ----------
93	
94	    @Test
95	    void lockdownTriggersThreeLevelLinkage() {
96	        String farm = "F-LOCK";
97	        stock(farm, Species.CATTLE, "TAG-A", 10);
98	        stock(farm, Species.CATTLE, "TAG-B", 10);
99	        // 一级：未出证申报。
100	        DeclarationView pending = declare("D-LK-PENDING", farm, Species.CATTLE, 3, "TAG-A");
101	        // 二级：已出证未启运。
102	        DeclarationView toVoid = declare("D-LK-VOID", farm, Species.CATTLE, 3, "TAG-A");
103	        CertificateView voided = issue("I-LK-VOID", toVoid.requestId());
104	        // 三级：已在途。
105	        DeclarationView inTransitDecl = declare("D-LK-TRANSIT", farm, Species.CATTLE, 4, "TAG-B");
106	        CertificateView inTransit = issue("I-LK-TRANSIT", inTransitDecl.requestId());
107	        depart(inTransit.certNo());
108	
109	        LockdownView lockdown = service.lockdown(new LockdownCmd("LK-1", farm, "口蹄疫疫点"));
110	        assertThat(lockdown.rejectedDeclarations()).isEqualTo(1);
111	        assertThat(lockdown.voidedCertificates()).isEqualTo(1);
112	        assertThat(lockdown.quarantinedInTransit()).isEqualTo(1);
113	
114	        // 一级结果：未出证申报被驳回，且驳回后不得出证。
115	        assertThat(service.getDeclaration(pending.requestId()).status())
116	                .isEqualTo(DeclarationStatus.REJECTED);
117	        assertThatThrownBy(() -> issue("I-LK-PENDING", pending.requestId()))
118	                .isInstanceOfSatisfying(ApiException.class, e ->
119	                        assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY));
120	
121	        // 二级结果：未启运证自动作废，落地报告被拒。
122	        CertificateView voidedAfter = service.getCertificate(voided.certNo());
123	        assertThat(voidedAfter.status()).isEqualTo(CertificateStatus.VOIDED);
124	        ArrivalView voidedArrival = service.arrive(new ArrivalCmd("A-LK-VOID", voided.certNo(), 3));
125	        assertThat(voidedArrival.result()).isEqualTo(ArrivalResult.REJECTED_CERT_INVALID);
126	
127	        // 三级结果：在途证强制隔离观察，仍允许完成落地并结案。
128	        CertificateView transitAfter = service.getCertificate(inTransit.certNo());
129	        assertThat(transitAfter.status()).isEqualTo(CertificateStatus.IN_TRANSIT);
130	        assertThat(transitAfter.quarantineObservation()).isTrue();
131	        ArrivalView transitArrival = service.arrive(new ArrivalCmd("A-LK-TRANSIT", inTransit.certNo(), 4));
132	        assertThat(transitArrival.result()).isEqualTo(ArrivalResult.ACCEPTED_FINAL);
133	        assertThat(transitArrival.quarantineObservation()).isTrue();
134	        assertThat(transitArrival.certStatus()).isEqualTo(CertificateStatus.CLOSED);
135	
136	        // 封锁即刻生效：新申报一律驳回，新出证被拒绝。
137	        DeclarationView afterLock = declare("D-LK-AFTER", farm, Species.CATTLE, 1, "TAG-A");
138	        assertThat(afterLock.status()).isEqualTo(DeclarationStatus.REJECTED);
139	        assertThat(afterLock.rejectReason()).contains("封锁");
140	    }
141	
142	    @Test
143	    void lockdownIsIdempotentByRequestIdAndByFarm() {
144	        String farm = "F-LK-IDEM";
145	        LockdownView first = service.lockdown(new LockdownCmd("LK-IDEM", farm, "禽流感疫点"));
146	        LockdownView replay = service.lockdown(new LockdownCmd("LK-IDEM", farm, "禽流感疫点"));
147	        assertThat(replay.createdAt()).isEqualTo(first.createdAt());
148	        assertThat(countRows("lockdown_zone")).isEqualTo(1);
149	
150	        // 同键异参 → 409。
151	        assertThatThrownBy(() -> service.lockdown(new LockdownCmd("LK-IDEM", farm, "另一种疫情")))
152	                .isInstanceOfSatisfying(ApiException.class, e ->
153	                        assertThat(e.status()).isEqualTo(HttpStatus.CONFLICT));
154	        // 同场新键：已有生效封锁，返回既有封锁，不重复联动。
155	        LockdownView second = service.lockdown(new LockdownCmd("LK-IDEM-2", farm, "禽流感疫点"));
156	        assertThat(second.requestId()).isEqualTo("LK-IDEM");
157	        assertThat(countRows("lockdown_zone")).isEqualTo(1);
158	    }
159	
160	    // ---------- 出证核减原子性 ----------
161	
162	    @Test
163	    void issueDecrementsStockAndGeneratesCertNoAtomically() {
164	        String farm = "F-STOCK";
165	        stock(farm, Species.SHEEP, "TAG-7", 10);
166	        DeclarationView declaration = declare("D-ST-1", farm, Species.SHEEP, 4, "TAG-7");
167	        CertificateView cert = issue("I-ST-1", declaration.requestId());
168	
169	        assertThat(cert.certNo()).startsWith("AQ");
170	        assertThat(stockQty(farm, Species.SHEEP, "TAG-7")).isEqualTo(6);
171	        assertThat(service.getDeclaration(declaration.requestId()).status())
172	                .isEqualTo(DeclarationStatus.CERTIFIED);
173	    }
