171	            List<T> results = new ArrayList<>();
172	            for (Future<T> future : futures) {
173	                results.add(future.get(30, TimeUnit.SECONDS));
174	            }
175	            return results;
176	        } finally {
177	            pool.shutdownNow();
178	            assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
