 */
public enum FlowPurpose {

    /** 本地销售（仅 LOCAL 证）。 */
    LOCAL_SALE,
    /** 饲养（仅 LOCAL 证）。 */
    BREEDING,
    /** 过境通行（仅 TRANSIT 证）。 */
    TRANSIT
}

package com.example.starter.quarantine;

/**
 * 过境超时预警事件状态：处理闭环 OPEN → RESOLVED。
 */
public enum TransitAlertStatus {

    /** 待处理。 */
    OPEN,
    /** 已办结。 */
    RESOLVED
}

